  1	/* ============================================================
  2	   views/strategy.js — Strategy view (Repository List + Detail/Editor)
  3	   Section 4g of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	
  8	/* ── renderStrategyList ──────────────────────────────────────
  9	   Renders the repository list at #/strategy.
 10	   Shows: label, folder names, vision status; Add Repository form.
 11	   Includes a "Show undeclared repositories" checkbox that re-fetches
 12	   with ?include_undeclared=true and renders undeclared entries with a
 13	   muted visual style and a "Register" button that pre-fills the form.
 14	   ─────────────────────────────────────────────────────────── */
 15	function renderStrategyList(app) {
 16	  showLoading(app);
 17	
 18	  API.listRepos(false).then(function (repos) {
 19	    renderList(repos, false);
 20	  }).catch(function (err) {
 21	    showError(app, 'Failed to load repositories: ' + (err.message || String(err)));
 22	  });
 23	
 24	  function visionStatus(repo) {
 25	    if (!repo.has_vision) return '<span class="badge badge-blocked">No vision</span>';
 26	    return repo.has_full_vision
 27	      ? '<span class="badge badge-complete">Full vision</span>'
 28	      : '<span class="badge badge-in-progress">Partial vision</span>';
 29	  }
 30	
 31	  /**
 32	   * Builds the checkbox toggle HTML for showing/hiding undeclared repositories.
 33	   * The checked state is preserved across re-renders so the UI doesn't flicker.
 34	   */
 35	  function buildToggleHtml(checked) {
 36	    return (
 37	      '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">' +
 38	        '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;user-select:none;font-size:14px">' +
 39	          '<input type="checkbox" id="show-undeclared-cb" class="form-check"' + (checked ? ' checked' : '') + '>' +
 40	          'Show undeclared repositories' +
 41	        '</label>' +
 42	      '</div>'
 43	    );
 44	  }
 45	
 46	  function buildTableHtml(repos) {
 47	    if (!repos.length) {
 48	      return '<p class="text-muted mt-16">No repositories declared yet. Use the form below to add one.</p>';
 49	    }
 50	    var rows = repos.map(function (r) {
 51	      var folderNames = (r.folder_names || []).map(escapeHtml).join(', ') || '<em class="text-muted">—</em>';
 52	      if (r.declared === false) {
 53	        /* Undeclared (filesystem-discovered) entry — muted row with Register button */
 54	        return (
 55	          '<tr style="opacity:0.6">' +
 56	            '<td>' +
 57	              '<span class="text-muted" style="font-style:italic">' + escapeHtml(r.label || r.id) + '</span>' +
 58	              ' <span class="badge badge-archived" style="font-size:10px;vertical-align:middle">Undeclared</span>' +
 59	            '</td>' +
 60	            '<td class="text-muted">' + escapeHtml(r.id) + '</td>' +
 61	            '<td class="text-muted">' + folderNames + '</td>' +
 62	            '<td>' +
 63	              '<button type="button" class="btn btn-secondary btn-sm" data-register-folder="' + escapeHtml(r.id) + '">Register</button>' +
 64	            '</td>' +
 65	          '</tr>'
 66	        );
 67	      }
 68	      return (
 69	        '<tr>' +
 70	          '<td><a href="#/strategy/' + encodeURIComponent(r.id) + '">' + escapeHtml(r.label || r.id) + '</a></td>' +
 71	          '<td class="text-muted">' + escapeHtml(r.id) + '</td>' +
 72	          '<td>' + folderNames + '</td>' +
 73	          '<td>' + visionStatus(r) + '</td>' +
 74	        '</tr>'
 75	      );
 76	    }).join('');
 77	    return (
 78	      '<table class="data-table">' +
 79	        '<thead><tr>' +
 80	          '<th>Label</th>' +
 81	          '<th>ID</th>' +
 82	          '<th>Folder Names</th>' +
 83	          '<th>Vision</th>' +
 84	        '</tr></thead>' +
 85	        '<tbody>' + rows + '</tbody>' +
 86	      '</table>'
 87	    );
 88	  }
 89	
 90	  /**
 91	   * Re-renders only the repo table and toggle, preserving the Add Repository
 92	   * form and its current field values. Called on checkbox toggle.
 93	   */
 94	  function refreshTable(checked) {
 95	    var toggleEl = document.getElementById('strategy-toggle-area');
 96	    var tableEl = document.getElementById('strategy-table-area');
 97	    if (toggleEl) toggleEl.innerHTML = buildToggleHtml(checked);
 98	    if (tableEl) tableEl.innerHTML = '<p class="text-muted" style="font-size:13px">Loading\u2026</p>';
 99	
100	    API.listRepos(checked).then(function (repos) {

101	      if (tableEl) tableEl.innerHTML = buildTableHtml(repos);
102	      wireRegisterButtons();
103	      wireToggle();
104	    }).catch(function (err) {
105	      if (tableEl) tableEl.innerHTML = '<p class="error-banner">Failed to load repositories: ' + escapeHtml(err.message || String(err)) + '</p>';
106	    });
107	  }
108	
109	  /** Wires the "Register" buttons on undeclared rows to pre-fill the Add form. */
110	  function wireRegisterButtons() {
111	    var tableEl = document.getElementById('strategy-table-area');
112	    if (!tableEl) return;
113	    tableEl.querySelectorAll('[data-register-folder]').forEach(function (btn) {
114	      btn.addEventListener('click', function () {
115	        var folderName = btn.getAttribute('data-register-folder');
116	        var idInput = document.getElementById('new-repo-id');
117	        var labelInput = document.getElementById('new-repo-label');
118	        var foldersInput = document.getElementById('new-repo-folders');
119	        if (idInput) idInput.value = folderName;
120	        if (labelInput) labelInput.value = folderName;
121	        if (foldersInput) foldersInput.value = folderName;
122	        /* Scroll the Add Repository form into view */
123	        var formCard = document.getElementById('add-repo-form');
124	        if (formCard) formCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
125	        if (idInput) idInput.focus();
126	      });
127	    });
128	  }
129	
130	  /** Wires the Show undeclared checkbox change handler after each re-render. */
131	  function wireToggle() {
132	    var cb = document.getElementById('show-undeclared-cb');
133	    if (!cb) return;
134	    cb.addEventListener('change', function () {
135	      refreshTable(cb.checked);
136	    });
137	  }
138	
139	  function renderList(repos, checked) {
140	    app.innerHTML =
141	      '<div class="page-header">' +
142	        '<h1>Strategy</h1>' +
143	        '<p class="text-muted">Manage repository declarations and strategic vision.</p>' +
144	      '</div>' +
145	      '<div id="strategy-toggle-area">' + buildToggleHtml(checked) + '</div>' +
146	      '<div id="strategy-table-area">' + buildTableHtml(repos) + '</div>' +
147	      '<div class="card mt-24" style="max-width:560px">' +
148	        '<h2 style="margin-top:0">Add Repository</h2>' +
149	        '<form id="add-repo-form">' +
150	          '<div class="form-group">' +
151	            '<label class="form-label" for="new-repo-id">ID <span class="text-muted">(slug, e.g. my-project)</span></label>' +
152	            '<input type="text" id="new-repo-id" class="form-control" placeholder="my-project" required>' +
153	          '</div>' +
154	          '<div class="form-group">' +
155	            '<label class="form-label" for="new-repo-label">Label</label>' +
156	            '<input type="text" id="new-repo-label" class="form-control" placeholder="My Project">' +
157	          '</div>' +
158	          '<div class="form-group">' +
159	            '<label class="form-label" for="new-repo-folders">Folder Names <span class="text-muted">(comma-separated)</span></label>' +
160	            '<input type="text" id="new-repo-folders" class="form-control" placeholder="my-project, my-project-dev">' +
161	          '</div>' +
162	          '<button type="submit" class="btn btn-primary">Add Repository</button>' +
163	          '<div id="add-repo-msg"></div>' +
164	        '</form>' +
165	      '</div>';
166	
167	    wireRegisterButtons();
168	    wireToggle();
169	
170	    var form = document.getElementById('add-repo-form');
171	    if (!form) return;
172	
173	    form.addEventListener('submit', function (e) {
174	      e.preventDefault();
175	      var msgEl = document.getElementById('add-repo-msg');
176	      var id = (document.getElementById('new-repo-id').value || '').trim();
177	      var label = (document.getElementById('new-repo-label').value || '').trim();
178	      var foldersRaw = (document.getElementById('new-repo-folders').value || '').trim();
179	      var folderNames = foldersRaw
180	        ? foldersRaw.split(',').map(function (f) { return f.trim(); }).filter(Boolean)
181	        : [];
182	
183	      if (!id) {
184	        msgEl.innerHTML = '<p class="error-banner">ID is required.</p>';
185	        return;
186	      }
187	
188	      if (!folderNames.length) {
189	        msgEl.innerHTML = '<p class="error-banner">At least one folder name is required.</p>';
190	        return;
191	      }
192	
193	      msgEl.innerHTML = '';
194	      API.createRepo({ id: id, label: label || id, folder_names: folderNames })
195	        .then(function () {
196	          Router.navigate('#/strategy/' + encodeURIComponent(id));
197	        })
198	        .catch(function (err) {
199	          msgEl.innerHTML = '<p class="error-banner">Failed to create repository: ' + escapeHtml(err.message || String(err)) + '</p>';
200	        });
201	    });
202	  }
203	}
204	
205	/* ── renderStrategyDetail ────────────────────────────────────
206	   Renders the repository detail/editor at #/strategy/:repoId.
207	   Shows: editable label, folder names (add/remove), three-field
208	          vision editor (short-term, mid-term, long-term),
209	          save button, breadcrumb navigation.
210	   ─────────────────────────────────────────────────────────── */
211	function renderStrategyDetail(app, repoId) {
212	  showLoading(app);
213	
214	  API.getRepo(repoId).then(function (repo) {
215	    renderDetail(repo);
216	  }).catch(function (err) {
217	    if (err.code === 'NOT_FOUND' || (err.message && err.message.indexOf('404') !== -1)) {
218	      showError(app, 'Repository not found: ' + escapeHtml(repoId));
219	    } else {
220	      showError(app, 'Failed to load repository: ' + (err.message || String(err)));
221	    }
222	  });
223	
224	  function buildFolderListHtml(folderNames) {
225	    if (!folderNames || !folderNames.length) {
226	      return '<p class="text-muted" id="folder-empty-note">No folder names added yet.</p>';
227	    }
228	    return folderNames.map(function (f, i) {
229	      return (
230	        '<div class="folder-entry" style="display:flex;align-items:center;gap:8px;margin-bottom:6px">' +
231	          '<input type="text" class="form-control folder-name-input" data-folder-idx="' + i + '" value="' + escapeHtml(f) + '" style="flex:1">' +
232	          '<button type="button" class="btn btn-danger btn-sm" data-remove-folder="' + i + '">Remove</button>' +
233	        '</div>'
234	      );
235	    }).join('');
236	  }
237	
238	  /* Reads all folder name inputs from the DOM in index order. */
239	  function collectFolderNamesFromDOM() {
240	    var result = [];
241	    document.querySelectorAll('.folder-name-input').forEach(function (inp) {
242	      var val = inp.value.trim();
243	      if (val) result.push(val);
244	    });
245	    return result;
246	  }
247	
248	  function renderDetail(repo) {
249	    var vision = repo.vision || {};
250	    /* Working copy — mutated by add/remove, then merged with DOM on save. */
251	    var folderNames = (repo.folder_names || []).slice();
252	
253	    function rebuildFolderSection() {
254	      var container = document.getElementById('folder-list');
255	      if (container) {
256	        container.innerHTML = buildFolderListHtml(folderNames);
257	        wireRemoveButtons();
258	      }
259	    }
260	
261	    function wireRemoveButtons() {
262	      var container = document.getElementById('folder-list');
263	      if (!container) return;
264	      container.querySelectorAll('[data-remove-folder]').forEach(function (btn) {
265	        btn.addEventListener('click', function () {
266	          /* Capture any in-flight edits before splicing */
267	          folderNames = collectFolderNamesFromDOM();
268	          var idx = parseInt(btn.getAttribute('data-remove-folder'), 10);
269	          folderNames.splice(idx, 1);
270	          rebuildFolderSection();
271	        });
272	      });
273	    }
274	
275	    app.innerHTML =
276	      '<div class="breadcrumb">' +
277	        '<a href="#/strategy">Strategy</a>' +
278	        ' &rsaquo; ' +
279	        escapeHtml(repo.label || repo.id) +
280	      '</div>' +
281	      '<div class="page-header">' +
282	        '<h1>' + escapeHtml(repo.label || repo.id) + '</h1>' +
283	        '<p class="text-muted">ID: <code>' + escapeHtml(repo.id) + '</code></p>' +
284	      '</div>' +
285	      '<div class="card" style="max-width:680px">' +
286	        '<form id="detail-form">' +
